import{_ as r,o as e,c as l,ai as a}from"./chunks/framework.BI5prboT.js";const p=JSON.parse('{"title":"面试怎么答：怎么写好一个 Skill","description":"","frontmatter":{},"headers":[],"relativePath":"AI/skill-interview.md","filePath":"AI/skill-interview.md"}'),o={name:"AI/skill-interview.md"};function d(i,t,n,s,h,c){return e(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="面试怎么答-怎么写好一个-skill" tabindex="-1">面试怎么答：怎么写好一个 Skill <a class="header-anchor" href="#面试怎么答-怎么写好一个-skill" aria-label="Permalink to &quot;面试怎么答：怎么写好一个 Skill&quot;">​</a></h1><p>高频原题：</p><blockquote><p>你们 Agent 里的 Skill 是怎么写的？怎么保证高质量？</p></blockquote><p>表面问写法，实际考 <strong>Agent 工程化</strong>：会不会抽象任务、会不会把专家判断写进系统、有没有质量闭环。</p><p>完整动手写法见：<a href="./create-skill.html">如何编写 Skill</a>；加载机制见：<a href="./skill-how.html">Skill 生效原理</a>。参考：<a href="https://mp.weixin.qq.com/s/iw_kM0bc8GfhZULWEclMHg" target="_blank" rel="noreferrer">字节面试题：怎么写好一个 Skill？</a></p><h2 id="一句话定调" tabindex="-1">一句话定调 <a class="header-anchor" href="#一句话定调" aria-label="Permalink to &quot;一句话定调&quot;">​</a></h2><p><strong>Skill 写得好不好，是信息架构题，不是文案题。</strong></p><p>Skill = 可复用<strong>任务能力单元</strong>，不是长 Prompt。目标是在一类任务上<strong>稳定、可控、可复用</strong>，而不是偶尔答得好。</p><h2 id="面试官在听什么" tabindex="-1">面试官在听什么 <a class="header-anchor" href="#面试官在听什么" aria-label="Permalink to &quot;面试官在听什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>想听到什么</th></tr></thead><tbody><tr><td>任务抽象</td><td>什么该 Skill 化，什么不该</td></tr><tr><td>专家沉淀</td><td>有没有决策树、反模式，而不只是步骤列表</td></tr><tr><td>质量保障</td><td>有没有验证、评测、迭代</td></tr></tbody></table><p>别一上来只说「我会写 <code>SKILL.md</code>」。先亮这三层，再落到做法。</p><h2 id="差答案-vs-好答案" tabindex="-1">差答案 vs 好答案 <a class="header-anchor" href="#差答案-vs-好答案" aria-label="Permalink to &quot;差答案 vs 好答案&quot;">​</a></h2><p><strong>差：</strong></p><blockquote><p>给 AI 写 Markdown 指令，告诉它什么时候触发、怎么做……</p></blockquote><p><strong>好：</strong></p><blockquote><p>Skill 是可复用任务能力单元，要有触发条件、专家决策逻辑、反模式约束、资源分层加载、验证闭环和迭代机制。</p></blockquote><h2 id="三层答题框架" tabindex="-1">三层答题框架 <a class="header-anchor" href="#三层答题框架" aria-label="Permalink to &quot;三层答题框架&quot;">​</a></h2><p>按 <strong>认知 → 设计 → 工程</strong> 递进即可。</p><h3 id="_1-认知" tabindex="-1">1. 认知 <a class="header-anchor" href="#_1-认知" aria-label="Permalink to &quot;1. 认知&quot;">​</a></h3><ul><li>Skill ≠ Prompt 模板；读者是 AI，不是人</li><li>少写背景、语气、版本记录；多写「现在该怎么判断」</li></ul><h3 id="_2-设计" tabindex="-1">2. 设计 <a class="header-anchor" href="#_2-设计" aria-label="Permalink to &quot;2. 设计&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要点</th><th>怎么说</th></tr></thead><tbody><tr><td><strong>值不值得做</strong></td><td>反复出现 + 够复杂 + 熟手/新手差距大 + 要质量；翻译、一次性活别硬塞</td></tr><tr><td><strong>上下文成本</strong></td><td><code>description</code> 常驻 → <code>SKILL.md</code> 触发后再读 → <code>scripts</code> / <code>references</code> 按需（见 <a href="./skill-how.html">生效原理</a>）</td></tr><tr><td><strong>专家判断</strong></td><td>条件决策树 + 「不做什么」；反模式比空泛的「保持专业」更能收窄行为</td></tr><tr><td><strong>自由度</strong></td><td>高风险（迁移、发布）低自由度、先计划再执行；分析类（评审）给框架、留空间</td></tr></tbody></table><h3 id="_3-工程" tabindex="-1">3. 工程 <a class="header-anchor" href="#_3-工程" aria-label="Permalink to &quot;3. 工程&quot;">​</a></h3><ul><li>脆弱、要一致的步骤 → <strong>脚本化</strong></li><li>多步且顺序重要 → <strong>Checklist</strong>，防漏步</li><li>关键步后 <strong>强制验证</strong>，失败则停</li><li>用「写 Skill / 用 Skill」双实例对照测，漏步、误触发、决策错了再改 Skill</li></ul><h2 id="常见追问" tabindex="-1">常见追问 <a class="header-anchor" href="#常见追问" aria-label="Permalink to &quot;常见追问&quot;">​</a></h2><table tabindex="0"><thead><tr><th>追问</th><th>接法要点</th></tr></thead><tbody><tr><td>好不好的标准？</td><td>稳定可复用；触发准、判断像专家、输出可验收、可迭代</td></tr><tr><td><code>description</code> 怎么写？</td><td>第三人称；做什么 + 何时用 + 触发词；忌「我可以帮你」</td></tr><tr><td>和普通文档区别？</td><td>文档给人读；Skill 是执行协议，有可检测步骤与禁区</td></tr><tr><td>和 MCP 关系？</td><td>Skill 管流程与判断；MCP 管外部连接；常组合（见 <a href="./skill-vs-mcp.html">异同</a>）</td></tr><tr><td>举个例子？</td><td>代码评审：决策树 + 分级输出 + 清单/脚本（见 <a href="./create-skill.html">如何编写 Skill</a>）</td></tr></tbody></table><h2 id="评分直觉" tabindex="-1">评分直觉 <a class="header-anchor" href="#评分直觉" aria-label="Permalink to &quot;评分直觉&quot;">​</a></h2><ul><li><strong>基础分</strong>：写过 Skill / 知道 <code>SKILL.md</code></li><li><strong>高分</strong>：讲清分层加载、<code>description</code>、决策树与反模式</li><li><strong>顶分</strong>：还能讲自由度光谱、Checklist、验证闭环、双实例迭代——说明真在项目里打磨过</li></ul><p>把「先想清楚 → description → 决策树 → 脚本与自检」说圆，这道题基本稳了。</p>',29)])])}const b=r(o,[["render",d]]);export{p as __pageData,b as default};
